import { Skeleton } from "@/components/ui";

/**
 * Loading skeleton for the product detail page.
 *
 * Preserves the approximate final layout (breadcrumb, hero grid with
 * gallery/info columns, feature cards and spec rows) so the swap from
 * skeleton to content causes minimal layout shift.
 */
export function ProductDetailSkeleton() {
  return (
    <div>
      {/* Breadcrumb */}
      <Skeleton className="h-4 w-48" />

      {/* Hero: gallery + info */}
      <div className="mt-6 grid gap-8 lg:grid-cols-2 xl:grid-cols-[1.05fr_1fr] xl:gap-12">
        <div className="space-y-3">
          <Skeleton className="aspect-square w-full rounded-lg" />
          <div className="flex gap-2 md:justify-start">
            {Array.from({ length: 4 }).map((_, i) => (
              <Skeleton key={i} className="size-16 rounded-md" />
            ))}
          </div>
        </div>

        <div className="space-y-5">
          <div className="flex gap-2">
            <Skeleton className="h-6 w-20 rounded-md" />
            <Skeleton className="h-6 w-24 rounded-md" />
          </div>
          <Skeleton className="h-9 w-3/4" />
          <Skeleton className="h-4 w-full" />
          <Skeleton className="h-4 w-2/3" />
          <div className="flex items-center gap-2">
            <Skeleton className="h-5 w-28" />
            <Skeleton className="h-4 w-20" />
          </div>
          <div className="space-y-2.5 border-t border-border pt-5">
            {Array.from({ length: 4 }).map((_, i) => (
              <Skeleton key={i} className="h-4 w-full" />
            ))}
          </div>
          <Skeleton className="h-44 w-full rounded-lg" />
        </div>
      </div>

      {/* Sections */}
      <div className="mt-12 space-y-12 lg:mt-16 lg:space-y-16">
        <div className="space-y-4">
          <Skeleton className="h-6 w-40" />
          <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
            {Array.from({ length: 3 }).map((_, i) => (
              <Skeleton key={i} className="h-32 rounded-lg" />
            ))}
          </div>
        </div>

        <div className="space-y-4">
          <Skeleton className="h-6 w-40" />
          <div className="grid gap-x-10 sm:grid-cols-2">
            {Array.from({ length: 6 }).map((_, i) => (
              <Skeleton key={i} className="h-4 w-full" />
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}